#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace fedspatial; namespace fs=std::filesystem;
static Matrix load(const fs::path&p){Matrix x;if(!read_matrix(p.string(),&x))throw std::runtime_error("missing "+p.string());return x;}
static WorkerInput makew(const fs::path&f,int id){Matrix d=load(f/("worker_"+std::to_string(id)+".txt"));WorkerInput w{Matrix(100,2),Matrix(100,1),Matrix(100,5)};for(int i=0;i<100;i++){w.sites(i,0)=d(i,0);w.sites(i,1)=d(i,1);w.z(i,0)=d(i,2);for(int j=0;j<5;j++)w.x(i,j)=d(i,j+3);}return w;}
int main(){fs::path f="sync_gpu/tests/fixtures/figure1_reference",o="results/figure1_cpp_gpu_faithful/parity";fs::create_directories(o);GpuContext c(0);GlobalParameters p{Matrix(5,1),Matrix(),Matrix(),.25,1.,.11};double coeff[5]={-1,2,3,-2,1};for(int i=0;i<5;i++)p.gamma(i,0)=coeff[i];std::ofstream out(o/"ind_gamma_p5_parity.csv");out<<"worker,quantity,row,column,python_value,cpp_value,abs_error,rel_error\n";double eg=0,ex=0,en=0;Matrix ag(5,1),ax(5,5);for(int id=0;id<10;id++){auto s=compute_ind_gamma_local(c,makew(f,id),p);Matrix pg=load(f/("ind_initial_worker_"+std::to_string(id)+"_gamma.txt")),px=load(f/("ind_initial_worker_"+std::to_string(id)+"_xx.txt"));for(int i=0;i<5;i++){double e=std::abs(pg(i,0)-s.gamma(i,0));eg=std::max(eg,e);}for(int i=0;i<25;i++){double e=std::abs(px.a[i]-s.xx.a[i]);ex=std::max(ex,e);}for(int i=0;i<5;i++)ag(i,0)+=s.gamma(i,0);for(int i=0;i<25;i++)ax.a[i]+=s.xx.a[i];}for(double&v:ag.a)v/=10;for(double&v:ax.a)v/=10;Matrix py=load(f/"ind_initial_global_gamma.txt");for(int i=0;i<5;i++)en=std::max(en,std::abs(py(i,0)-ag(i,0)));Matrix gn=solve_spd(ax,ag),pgn=load(f/"ind_initial_gamma_new.txt");for(int i=0;i<5;i++)en=std::max(en,std::abs(pgn(i,0)-gn(i,0)));std::cout<<"IND_GAMMA_LOCAL_MAX_ERROR="<<eg<<"\nIND_XX_MAX_ERROR="<<ex<<"\nIND_GAMMA_NEW_MAX_ERROR="<<en<<"\nIND_GAMMA_PARITY="<<(std::max({eg,ex,en})<1e-10?"PASS":"FAIL")<<"\n";return 0;}
